package com.bank.minwindow;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Finds the tightest covering code window for National Bank of India.
public class MinWindowFinder {
    private static final Logger log = Logger.getLogger(MinWindowFinder.class.getName());

    // Minimum window containing all target chars (with counts). O(n), O(alphabet).
    public String minWindow(String source, String target) {
        if (source == null || target == null || target.isEmpty() || source.length() < target.length()) {
            return "";
        }
        Map<Character, Integer> need = new HashMap<>();
        for (char c : target.toCharArray()) {
            need.merge(c, 1, Integer::sum);          // required counts
        }
        int required = need.size();                   // distinct chars needed
        Map<Character, Integer> window = new HashMap<>();
        int formed = 0;                               // distinct chars fully satisfied
        int left = 0;
        int bestLen = Integer.MAX_VALUE, bestStart = 0;
        for (int right = 0; right < source.length(); right++) {
            char c = source.charAt(right);
            window.merge(c, 1, Integer::sum);
            if (need.containsKey(c) && window.get(c).intValue() == need.get(c).intValue()) {
                formed++;                             // this requirement just met
            }
            // Contract while the window is valid.
            while (formed == required) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;                 // new tightest window
                }
                char lc = source.charAt(left);
                window.merge(lc, -1, Integer::sum);
                if (need.containsKey(lc) && window.get(lc) < need.get(lc)) {
                    formed--;                         // requirement broken → stop shrink
                }
                left++;
            }
        }
        String result = bestLen == Integer.MAX_VALUE ? "" : source.substring(bestStart, bestStart + bestLen);
        log.info(() -> "Minimum window = '" + result + "'");
        return result;
    }
}
