package com.bank.minwindow;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: tightest covering code window.
public class MinWindowDemo {
    private static final Logger log = Logger.getLogger(MinWindowDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        MinWindowFinder finder = new MinWindowFinder();

        log.info(() -> "Window = '" + finder.minWindow("ADOBECODEBANC", "ABC") + "'"); // "BANC"
        log.info(() -> "Window = '" + finder.minWindow("DCCTC", "CC") + "'");           // "CC"
        log.info(() -> "Window = '" + finder.minWindow("DD", "ABC") + "'");             // ""
    }
}
